use super::*;

pub(super) fn entries() -> Vec<(String, String)> {
    let svgs = [
        "data:image/svg+xml;base64, ",
        "data:image/svg+xml;base64, PHN2ZyBlbmFibGUtYmFja2dyb3VuZD0ibmV3IDAgMCA0MiA0MiIgdmlld0JveD0iMCAwIDQyIDQyIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjxwYXRoIGQ9Im0yMC44IDguMy0yLjggMy0uOS0xIDMuOC00aDEuM3YxNy4zaC0xLjV2LTE1LjN6IiBmaWxsPSIjMDAzODgzIi8+PC9zdmc+",
        "data:image/svg+xml;base64, ",
        "data:image/svg+xml;base64, ",
        "data:image/svg+xml;base64, ",
        "data:image/svg+xml;base64, ",
        "data:image/svg+xml;base64, ",
        "data:image/svg+xml;base64, ",
        "data:image/svg+xml;base64, ",
        "data:image/svg+xml;base64, ",
    ];
    let keys = [
        "AAA", "AAB", "AAC", "AAD", "AAE", "AAF", "AAG", "AAH", "AAI", "AAJ",
    ];
    (0..10)
        .map(|digit| (keys[digit].to_owned(), svgs[digit].to_owned()))
        .collect()
}

pub(super) fn keyboard(entries: &[(String, String)]) -> String {
    let mut page = String::from(
        r#"<script>$("[data-matrix-random-challenge]").val("fixture-challenge");</script>"#,
    );
    for (key, svg) in entries {
        page.push_str(&format!(
            r#"<button data-matrix-key="{key}"><img src="{svg}"></button>"#
        ));
    }
    page
}

fn invalid_keyboards() -> Vec<(&'static str, String)> {
    let valid = entries();
    let mut cases = vec![("zero", keyboard(&[])), ("nine", keyboard(&valid[..9]))];
    for (name, index, replacement) in [
        ("empty key", 0, String::new()),
        ("blank key", 0, "   ".into()),
        ("duplicate key", 0, valid[1].0.clone()),
    ] {
        let mut changed = valid.clone();
        changed[index].0 = replacement;
        cases.push((name, keyboard(&changed)));
    }
    let mut duplicate = valid.clone();
    duplicate[9].1 = valid[0].1.clone();
    cases.push(("duplicate digit", keyboard(&duplicate)));
    let mut extra = valid.clone();
    extra.push(valid[0].clone());
    cases.push(("eleven", keyboard(&extra)));
    for svg in [
        "data:image/svg+xml;base64,PRIVATE_RESPONSE",
        "PRIVATE_RESPONSE",
    ] {
        let mut unknown = valid.clone();
        unknown[9].1 = svg.into();
        cases.push(("unknown SVG", keyboard(&unknown)));
        let mut extra = valid.clone();
        extra.push(("AAK".into(), svg.into()));
        cases.push(("extra unknown SVG", keyboard(&extra)));
    }
    let mut missing = valid.clone();
    missing[9].1 = String::new();
    cases.push(("missing image", keyboard(&missing)));
    cases
}

#[test]
fn actual_absent_pad_is_rejected() {
    assert!(
        virtual_pad::extract_data_matrix_keys(&keyboard(&[])).is_err(),
        "a challenge with zero actual buttons must not initialize ten empty keys"
    );
}

#[test]
fn invalid_pads_are_errors_and_never_post_login() {
    use super::auth_tests::{assert_safe_error, config_page, run, with_responses};
    for (name, page) in invalid_keyboards() {
        assert!(
            virtual_pad::extract_data_matrix_keys(&page).is_err(),
            "{name}"
        );
        for enabled in [true, false] {
            let (_, logs) = super::logging_tests::capture(enabled, || {
                let (_, requests) = with_responses(
                    vec![
                        (200, "__brs_mit=fixture-cookie;".into()),
                        (
                            200,
                            format!(
                                r#"<input name="form[_token]" value="fixture-token" > {}"#,
                                config_page(None)
                            ),
                        ),
                        (200, page.clone()),
                    ],
                    |client| {
                        // A failed reinitialization must invalidate a previously ready keyboard.
                        client.virtual_pad_ids =
                            entries().into_iter().map(|entry| entry.0).collect();
                        assert_safe_error(run(client.init_session()), "virtual pad");
                        assert_safe_error(run(client.login("PRIVATE_RESPONSE", "0")), "session");
                    },
                );
                assert_eq!(requests.len(), 3, "{name}");
                assert!(requests.iter().all(|request| request.starts_with("GET ")));
            });
            assert!(!logs.contains("PRIVATE_RESPONSE"));
        }
    }
}

#[test]
fn all_digits_and_repetitions_encode_exactly() {
    let page = keyboard(&entries());
    let keys = virtual_pad::extract_data_matrix_keys(&page)
        .unwrap()
        .map(str::to_owned)
        .to_vec();
    assert_eq!(
        virtual_pad::password_to_virtual_pad_keys(keys, "01234567899800").unwrap(),
        [
            "AAA", "AAB", "AAC", "AAD", "AAE", "AAF", "AAG", "AAH", "AAI", "AAJ", "AAJ", "AAI",
            "AAA", "AAA"
        ]
    );
}

#[test]
fn invalid_passwords_and_incomplete_states_never_send() {
    use super::auth_tests::{assert_safe_error, run};
    use std::{net::TcpListener, time::Duration};
    let valid: Vec<String> = entries().into_iter().map(|entry| entry.0).collect();
    let mut states = vec![vec![], valid[..9].to_vec(), vec!["AAA".into(); 10]];
    let mut empty = valid.clone();
    empty[9].clear();
    states.push(empty);
    let mut blank = valid.clone();
    blank[9] = " ".into();
    states.push(blank);
    let mut extra = valid.clone();
    extra.push("AAK".into());
    states.push(extra);
    let mut cases: Vec<_> = states
        .into_iter()
        .map(|state| (state, "0", "session"))
        .collect();
    for password in ["", "PRIVATE_RESPONSE", "0é", "0💣", "１２", "1 2"] {
        cases.push((valid.clone(), password, "password"));
    }
    for (keys, password, stage) in cases {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let mut client =
            BoursoWebClient::for_test(listener.local_addr().unwrap(), Duration::from_millis(100))
                .unwrap();
        let encoded = virtual_pad::password_to_virtual_pad_keys(keys.clone(), password);
        assert_safe_error(
            encoded,
            if stage == "session" {
                "virtual pad"
            } else {
                stage
            },
        );
        client.virtual_pad_ids = keys;
        let (_, logs) = super::logging_tests::capture(true, || {
            let error = run(client.login("PRIVATE_RESPONSE", password)).unwrap_err();
            let diagnostic = format!("{error:#} {error:?}");
            for secret in ["PRIVATE_RESPONSE", "é", "💣", "１２"] {
                assert!(!diagnostic.contains(secret));
            }
            assert_safe_error::<()>(Err(error), stage);
        });
        assert!(!logs.contains("PRIVATE_RESPONSE"));
        listener.set_nonblocking(true).unwrap();
        assert_eq!(
            listener.accept().unwrap_err().kind(),
            std::io::ErrorKind::WouldBlock
        );
    }
}
